const body = $input.first().json.body || {};
const invoice_text = String(body.text || body.invoice_text || '').replace(/\r/g, '').trim();

return [{json: {
  invoice_text: invoice_text.slice(0, 20000),
  input_ok: invoice_text.length >= 15,
  truncated: invoice_text.length > 20000
}}];

const input = $input.first().json;
const invoice = input.invoice_text;
const lines = invoice.split('\n').map(s => s.trim()).filter(Boolean);

function find(pattern) {
  const match = invoice.match(pattern);
  return match ? match[1].trim() : null;
}
function money(value) {
  if (!value) return null;
  let cleaned = value.replace(/[^\d.,]/g, '');
  if (cleaned.includes(',')) cleaned = cleaned.replace(/\./g, '').replace(',', '.');
  else if ((cleaned.match(/\./g) || []).length > 1) cleaned = cleaned.replace(/\./g, '');
  const number = Number(cleaned);
  return Number.isFinite(number) ? Math.round(number * 100) / 100 : null;
}
function date_iso(value) {
  if (!value) return null;
  const match = value.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})$/);
  if (!match) return null;
  const day = Number(match[1]);
  const month = Number(match[2]);
  const year = Number(match[3]);
  const date = new Date(Date.UTC(year, month - 1, day));
  if (date.getUTCDate() !== day || date.getUTCMonth() !== month - 1) return null;
  return date.toISOString().slice(0, 10);
}

const supplier = lines.find(line => !/^(rechnung|invoice|datum|date|seite|page)/i.test(line)) || null;
const invoice_no = find(/(?:Rechnungsnummer|Rechnungs[-\s]?Nr\.?|Invoice\s*(?:number|no\.?))\s*[:#]?\s*([A-Za-z0-9\/-]{3,30})/i);
const date_text = find(/(?:Rechnungsdatum|Invoice\s*Date|Datum|Date)\s*[:\-]?\s*(\d{1,2}[.\/-]\d{1,2}[.\/-]\d{4})/i);
const gross_text = find(/(?:Gesamtbetrag(?:\s+brutto)?|Rechnungsbetrag|Bruttobetrag|Zu\s+zahlen|Total|Summe\s+brutto)\s*[:=]?\s*(?:EUR\s*|€\s*)?([\d.,]+)/i);
const iban_match = invoice.match(/\bDE(?:[\s-]*\d){20}\b/i);
const iban = iban_match ? iban_match[0].replace(/[\s-]/g, '').toUpperCase() : null;
const vat_match = invoice.match(/(?:MwSt\.?|USt\.?|Umsatzsteuer)\s*(\d{1,2})\s*%\s*[:=]?\s*([\d.,]+)/i);

return [{json: {
  supplier: supplier,
  invoice_no: invoice_no,
  invoice_date: date_iso(date_text),
  gross_eur: money(gross_text),
  vat_rate: vat_match ? Number(vat_match[1]) : null,
  vat_eur: vat_match ? money(vat_match[2]) : null,
  iban: iban,
  input_ok: input.input_ok,
  truncated: input.truncated
}}];

const data = $input.first().json;
const errors = [];
const warnings = [];

function valid_iban(iban) {
  if (!iban || !/^DE\d{20}$/.test(iban)) return false;
  const moved = iban.slice(4) + iban.slice(0, 4);
  let remainder = 0;
  for (const character of moved) {
    const digits = /[A-Z]/.test(character) ? String(character.charCodeAt(0) - 55) : character;
    for (const digit of digits) remainder = (remainder * 10 + Number(digit)) % 97;
  }
  return remainder === 1;
}

if (!data.input_ok) errors.push('Invoice text is missing or too short');
if (!data.supplier) errors.push('Supplier not found');
if (!data.invoice_no) errors.push('Invoice number not found');
if (!data.invoice_date) errors.push('Invoice date not found');
if (data.gross_eur === null || data.gross_eur <= 0) errors.push('Total amount not found');
if (data.iban && !valid_iban(data.iban)) warnings.push('IBAN checksum is invalid');
if (!data.iban) warnings.push('No IBAN found');
if (data.truncated) warnings.push('Input was shortened to 20000 characters');
if (data.vat_rate !== null && data.vat_eur === null) warnings.push('VAT amount was not read');

const present = [data.supplier,data.invoice_no,data.invoice_date,data.gross_eur].filter(x => x !== null && x !== '').length;
const confidence = Math.max(0, Math.round((present / 4) * 100 - warnings.length * 5));
const needs_review = errors.length > 0 || warnings.includes('IBAN checksum is invalid');

return [{json: {
  project: 'invoice_parser',
  status: needs_review ? 'needs_review' : 'ready',
  needs_review: needs_review,
  confidence: confidence,
  invoice: {
    supplier: data.supplier,
    invoice_no: data.invoice_no,
    invoice_date: data.invoice_date,
    gross_eur: data.gross_eur,
    vat_rate: data.vat_rate,
    vat_eur: data.vat_eur,
    iban: data.iban
  },
  errors: errors,
  warnings: warnings
}}];
